156		// Status 的账单摘要与 GetBill 同源，反映查询时点：一月已付 1200、结清。
157		// 重报不能把已结清账单恢复成欠款；当前生效套餐仍是重新开通的 plan2400。
158		st, err = s.Status("u")
159		if err != nil {
160			t.Fatalf("status after replay: %v", err)
161		}
162		if !st.Subscribed || st.CurrentTerms != plan2400Terms {
163			t.Fatalf("current terms changed by replay: %+v", st.CurrentTerms)
164		}
165		if st.Suspended {
166			t.Fatalf("settled account must not be suspended: %+v", st.Bills)
167		}
168		if len(st.Bills) != 1 || st.Bills[0].Period != jan(2026) ||
169			st.Bills[0].TotalDue != 1200 || st.Bills[0].Paid != 1200 ||
170			st.Bills[0].Balance != 0 || !st.Bills[0].Settled {
171			t.Fatalf("status jan summary after replay: %+v", st.Bills)
172		}
173	
174		// 旧标识不能拿来登记新付款：保持一月账期但金额改成 501，冲突。
175		if _, err := s.RecordPayment("u", "pay-old", jan(2026), 501); !errors.Is(err, ErrPaymentConflict) {
176			t.Fatalf("old id with changed amount: %v", err)
177		}
