179		// 也不能改报成 ErrBillNotFound。
180		if _, err := s.RecordPayment("u", "pay-old", mar(2026), 500); !errors.Is(err, ErrPaymentConflict) {
181			t.Fatalf("old id repointed to unbilled march: %v", err)
182		} else if errors.Is(err, ErrBillNotFound) {
183			t.Fatalf("old id repointed to unbilled march must be conflict, got bill not found")
184		}
185	
186		// 冲突不消耗标识、不改数据：原样重报仍返回首次结果，一月仍结清，
187		// 重新开通生效的套餐不变。
188		replay2, err := s.RecordPayment("u", "pay-old", jan(2026), 500)
189		if err != nil || replay2.Registered || replay2.BillBalance != 700 || replay2.Settled {
190			t.Fatalf("replay after conflicts: %+v %v", replay2, err)
191		}
192		wantBillPaymentState(t, s, jan(2026), 1200, 1200, 0, true)
193	
194		// 四月月初为三月出账：按重新开通的 plan2400 计 2400，一月金额不受影响。
195		clk.t = utc(2026, 4, 1, 0, 0)
196		marBill, err := s.CreateBill("u", mar(2026))
197		if err != nil {
198			t.Fatalf("create march bill: %v", err)
199		}
200		if marBill.TotalDue != 2400 || marBill.Paid != 0 || marBill.Balance != 2400 || marBill.Settled {
201			t.Fatalf("march bill initial state: %+v", marBill)
202		}
203		if marBill.Terms != plan2400Terms {
204			t.Fatalf("march bill terms = %+v, want plan2400 snapshot", marBill.Terms)
205		}
206	
207		// 三月账单生成后沿用旧标识：改金额、改账期两种方式仍都冲突。
208		if _, err := s.RecordPayment("u", "pay-old", jan(2026), 501); !errors.Is(err, ErrPaymentConflict) {
209			t.Fatalf("old id changed amount after march billed: %v", err)
210		}
211		if _, err := s.RecordPayment("u", "pay-old", mar(2026), 500); !errors.Is(err, ErrPaymentConflict) {
212			t.Fatalf("old id repointed to billed march: %v", err)
213		}
214	
215		// 两张账单与原付款结果均保持冲突前的样子。
216		wantBillPaymentState(t, s, jan(2026), 1200, 1200, 0, true)
217		wantBillPaymentState(t, s, mar(2026), 2400, 0, 2400, false)
218		replay3, err := s.RecordPayment("u", "pay-old", jan(2026), 500)
219		if err != nil || replay3.Registered || replay3.Payment.Amount != 500 ||
220			replay3.Payment.Period != jan(2026) || replay3.BillBalance != 700 || replay3.Settled {
221			t.Fatalf("original payment result after march conflicts: %+v %v", replay3, err)
222		}
223	
224		// 换用未使用过的标识登记三月 500：正常成功，三月已付 500、余额 1900。
225		marPay, err := s.RecordPayment("u", "pay-mar-new", mar(2026), 500)
226		if err != nil {
227			t.Fatalf("fresh id march payment 500: %v", err)
228		}
229		if !marPay.Registered || marPay.Payment.PaymentID != "pay-mar-new" ||
230			marPay.Payment.Period != mar(2026) || marPay.Payment.Amount != 500 ||
231			marPay.BillBalance != 1900 || marPay.Settled {
232			t.Fatalf("fresh march payment result: %+v", marPay)
233		}
234		wantBillPaymentState(t, s, mar(2026), 2400, 500, 1900, false)
235		// 一月仍保持结清，不被三月付款或任何重报/冲突改动。
236		wantBillPaymentState(t, s, jan(2026), 1200, 1200, 0, true)
237	
238		// Status 同时给出两张账单摘要（按账期排列）与重新开通后生效的套餐。
239		st, err = s.Status("u")
240		if err != nil {
241			t.Fatalf("final status: %v", err)
242		}
243		if !st.Subscribed || st.CurrentTerms != plan2400Terms {
244			t.Fatalf("final current terms = %+v, want plan2400", st.CurrentTerms)
245		}
246		wantSummaries := []struct {
247			period         Month
248			due, paid, bal int64
249			settled        bool
250		}{
251			{jan(2026), 1200, 1200, 0, true},
252			{mar(2026), 2400, 500, 1900, false},
253		}
254		if len(st.Bills) != len(wantSummaries) {
255			t.Fatalf("final status bills = %+v, want %d summaries", st.Bills, len(wantSummaries))
256		}
257		for i, w := range wantSummaries {
258			got := st.Bills[i]
259			if got.Period != w.period || got.TotalDue != w.due || got.Paid != w.paid ||
260				got.Balance != w.bal || got.Settled != w.settled {
261				t.Fatalf("status bills[%d] = %+v, want period=%s due=%d paid=%d balance=%d settled=%v",
262					i, got, w.period, w.due, w.paid, w.bal, w.settled)
263			}
264		}
265	
266		// 补一笔边界：补齐标识 pay-rest 也只在本账户、一月、700 的原样重报时幂等，
267		// 改指三月同样冲突，不影响三月账单。
268		if _, err := s.RecordPayment("u", "pay-rest", mar(2026), 700); !errors.Is(err, ErrPaymentConflict) {
269			t.Fatalf("pay-rest repointed to march: %v", err)
270		}
271		wantBillPaymentState(t, s, mar(2026), 2400, 500, 1900, false)
272	}
